import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"sdkgen-webidl backend and the JS emitters","description":"","frontmatter":{"title":"`sdkgen-webidl` backend and the JS emitters","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"accepted","status_note":"Accepted — extracted in ADR-0128 Phase 5."},"headers":[],"relativePath":"web/project/adrs/0137-sdkgen-webidl-and-js-emitters.md","filePath":"vendored/web/project/adrs/0137-sdkgen-webidl-and-js-emitters.md"}'),a={name:`web/project/adrs/0137-sdkgen-webidl-and-js-emitters.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0137-sdkgen-webidl-backend-and-the-js-emitters" tabindex="-1">ADR-0137: <code>sdkgen-webidl</code> backend and the JS emitters <a class="header-anchor" href="#adr-0137-sdkgen-webidl-backend-and-the-js-emitters" aria-label="Permalink to “ADR-0137: sdkgen-webidl backend and the JS emitters”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><a href="./../0113-handl-sdkgen-webidl-js.html">ADR-0113</a> and <a href="./../0115-handl-sdkgen-dts-js.html">ADR-0115</a> add WebIDL/JS and TypeScript declaration emission on top of the SDK-generator port (<a href="./../0107-handl-sdk-generator.html">ADR-0107</a>); <a href="./../0121-webidl-cross-spec-includes.html">ADR-0121</a> handles supplementary mixin specs. These are web-platform concerns, not platform machinery.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><code>web</code> owns the WebIDL backend and the JS-family emitters: <code>plugin-sdkgen-backend-webidl</code> (target <code>webidl</code>) and the JS/<code>.d.ts</code> emitter layer, together with the 13 <code>generated/*-webidl-browser/</code> output trees and the <code>.webidl</code>/<code>.idl</code> spec inputs.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The <code>webidl</code> target name is preserved (the CLI keeps <code>hnl sdkgen webidl</code>); the repo is <code>web</code>, the module is <code>sdkgen-webidl</code> — repo ≠ target.</li><li><code>webidl</code> consumes the <code>c</code> backend the same way <code>python</code> does, so a WebIDL flow is backend <code>c</code> + emitter <code>webidl</code> unless a pure-IDL backend is added.</li><li>Spec inputs stay gitignored; generated output is committed.</li></ul>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};